<?php $problem=$problem??[]; ?>
<?php foreach(\Morshed\Product\PersonalProblems::FIELDS as $key=>$label): ?><label><?= $this->h($label) ?><?php if($key==='title'): ?><input name="title" maxlength="180" required value="<?= $this->h($problem[$key]??'') ?>"><?php else: ?><textarea name="<?= $key ?>" maxlength="6000" rows="3" required><?= $this->h($problem[$key]??'') ?></textarea><?php endif; ?></label><?php endforeach; ?>
<label>مجموعهٔ مرتبط (اختیاری)<select name="org_id"><option value="">مسئلهٔ شخصی؛ بدون مجموعه</option><?php foreach($memberOrganizations??[] as $org): ?><option value="<?= $this->h($org['id']) ?>" <?= ($problem['org_id']??'')===$org['id']?'selected':'' ?>><?= $this->h($org['name']) ?></option><?php endforeach; ?></select></label>
<details><summary>موضوع‌ها، برچسب‌های مسئله و تجربه‌های مرتبط (اختیاری)</summary><div class="membership-options"><?php foreach($terms??[] as $t): ?><label class="check"><input type="checkbox" name="terms[]" value="<?= $this->h($t['id']) ?>" <?= in_array($t['id'],$problem['terms']??[],true)?'checked':'' ?>><?= $this->h(($t['kind']==='topic'?'موضوع: ':'مسئله: ').$t['title']) ?></label><?php endforeach; ?></div><div class="membership-options"><?php foreach($problemExperiences??$experiences??[] as $exp): ?><label class="check"><input type="checkbox" name="experiences[]" value="<?= $this->h($exp['id']) ?>" <?= in_array($exp['id'],$problem['experiences']??[],true)?'checked':'' ?>><?= $this->h($exp['title']) ?></label><?php endforeach; ?></div></details>
